class Solution {
public:
    int findNumbers(vector<int>& nums) {
        int count = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            int x = nums[i], digits = 0;
            while (x > 0) {
                x /= 10;
                digits++;
            }
            if (digits % 2 == 0) count++;
        }
        return count;
    }
};
